#[tokio::test]
async fn account_api_key_omits_default_store() {
    let server = MockServer::start().await;
    Mock::given(method("GET"))
        .respond_with(ResponseTemplate::new(200).set_body_json(json!({})))
        .mount(&server)
        .await;
    let client = Client::new("account-key", "configured-store")
        .with_base_url(server.uri())
        .with_max_retries(0);
    for route in ["/v2/me", "/v2/stores", "/v2/stores/12", "/v2/products"] {
        client
            .custom_request(Method::GET, route, json!({}), None, None)
            .await
            .unwrap();
    }
    let requests = server.received_requests().await.unwrap();
    assert_eq!(requests.len(), 4);
    for request in &requests {
        assert_eq!(
            request.headers.get("authorization").unwrap(),
            "Bearer account-key"
        );
    }
    for request in &requests[..3] {
        assert!(!request.headers.contains_key("x-store"));
    }
    assert_eq!(
        requests[3].headers.get("x-store").unwrap(),
        "configured-store"
    );
}

