#[tokio::test]
async fn oauth_form_arrays_origin_errors_and_no_retry() {
    let server = MockServer::start().await;
    Mock::given(path("/oauth/token"))
        .respond_with(
            ResponseTemplate::new(503).set_body_json(
                json!({"error":"invalid_grant","error_description":"Authorize again"}),
            ),
        )
        .expect(1)
        .mount(&server)
        .await;
    let client = Client::new("seller", "store")
        .with_base_url(format!("{}/api", server.uri()))
        .with_max_retries(2);
    let error = client
        .custom_request(
            Method::POST,
            "/oauth/token",
            json!({}),
            Some(json!({"grant_type":"authorization_code","store_ids":["1","2"]})),
            None,
        )
        .await
        .unwrap_err();
    match error {
        Error::Api(error) => {
            assert_eq!(error.code.as_deref(), Some("invalid_grant"));
            assert_eq!(error.message, "Authorize again")
        }
        other => panic!("{other:?}"),
    }
    let requests = server.received_requests().await.unwrap();
    assert_eq!(requests.len(), 1);
    assert_eq!(
        requests[0].headers.get("content-type").unwrap(),
        "application/x-www-form-urlencoded"
    );
    let body = String::from_utf8(requests[0].body.clone()).unwrap();
    assert!(body.contains("store_ids%5B%5D=1") && body.contains("store_ids%5B%5D=2"));
    assert!(!requests[0].headers.contains_key("authorization"));
}
