#[tokio::test]
async fn generated_authorization_preserves_html_and_manual_redirect_metadata() {
    use sellapp::resources::oauth::GetOAuthAuthorizationRequestParams;
    let server = MockServer::start().await;
    let html = "<!doctype html><html><body>Allow &amp; continue?\n<form>✓</form></body></html>";
    let params = || {
        GetOAuthAuthorizationRequestParams::new(
            "code",
            "00000000-0000-4000-8000-000000000000",
            "http://127.0.0.1:4567/callback",
            "fresh-state",
            "a".repeat(43),
            "S256",
        )
    };
    let client = Client::new("seller", "store").with_base_url(server.uri());
    Mock::given(path("/oauth/authorize"))
        .respond_with(
            ResponseTemplate::new(200)
                .set_body_raw(html, "text/html; charset=utf-8")
                .insert_header("X-Request-ID", "html-request"),
        )
        .expect(2)
        .mount(&server)
        .await;
    assert_eq!(
        client
            .oauth()
            .get_oauth_authorization_request(params())
            .await
            .unwrap(),
        html
    );
    let wrapped = client
        .oauth()
        .get_oauth_authorization_request_raw(params(), None)
        .await
        .unwrap();
    assert_eq!(wrapped.data, html);
    assert_eq!(wrapped.status, 200);
    assert_eq!(
        wrapped.headers.get("content-type").unwrap(),
        "text/html; charset=utf-8"
    );
    assert_eq!(wrapped.request_id.as_deref(), Some("html-request"));
    server.verify().await;
    server.reset().await;
    Mock::given(path("/oauth/authorize"))
        .respond_with(
            ResponseTemplate::new(302)
                .set_body_string(html)
                .insert_header("Location", "https://other.invalid/callback"),
        )
        .expect(1)
        .mount(&server)
        .await;
    let redirect = client
        .oauth()
        .get_oauth_authorization_request_raw(params(), None)
        .await
        .unwrap();
    assert_eq!(redirect.data, html);
    assert_eq!(redirect.status, 302);
    assert_eq!(
        redirect.headers.get("location").unwrap(),
        "https://other.invalid/callback"
    );
    assert_eq!(server.received_requests().await.unwrap().len(), 1);
}
